import itertools
views=[('V','X'),('X','Z')]
faces=['V','X','Z','W','Y']
sols=set()
for rest in itertools.permutations(['W','Y','Z','X','V'],4):
    p=rest
    if p[0]!='V': continue
    if all(any(p[i]==a and p[(i+1)%4]==b for i in range(4)) for a,b in views):
        sols.add(p[2])
